script.code:
// PO_SAVE pre-save checks in ONE pass over the payload (replaces Draft Check Doc No, Draft Required Fields, Check Doc No,
// Required Fields, Map Validate Quantity, Filter unnecessary line, Count line, Direct PI Zero Total Check and Map Approval
// PO Data, which each copied the whole payload). CHECK_REQUIRED_FIELD / VALIDATE_QUANTITY / CHECK_APPROVAL get only the
// fields they read; Fillback Header Fields rebuilds the record from the payload itself.
const a = {{workflowparams:allData}} || {};
const isDraft = a.po_status == "Draft";
const rows = a.table_po;
const list = Array.isArray(rows) ? rows : [];

// Doc number marker, as Draft Check Doc No / Check Doc No set it
let docNo = a.purchase_order_no;
const noNumber = !a.purchase_order_no || a.purchase_order_no === null || a.purchase_order_no === "";
if (a.purchase_order_no_type !== -9999) {
  if (isDraft && noNumber) docNo = "draft";
  if (!isDraft && (noNumber || a.previous_status == "Draft")) docNo = "issued";
}

// CHECK_REQUIRED_FIELD reads table_po only as "a non-empty array" (arrayFields is empty)
const tableForCheck = Array.isArray(rows) ? (rows.length > 0 ? [{}] : []) : null;
const tableField = { name: "table_po", label: "Item Information", isArray: true, arrayType: "object", arrayFields: [] };
const draftRequiredFields = JSON.stringify([{ name: "po_plant", label: "Plant" }, { name: "purchase_order_no", label: "PO Number" }, tableField]);
const draftRequiredEntry = JSON.stringify({ po_plant: a.po_plant, purchase_order_no: docNo, table_po: tableForCheck });
const requiredFields = JSON.stringify([
  { name: "po_supplier_id", label: "Supplier Name" },
  { name: "po_plant", label: "Plant" },
  { name: "purchase_order_no", label: "PO Number" },
  tableField,
]);
const requiredEntry = JSON.stringify({ po_supplier_id: a.po_supplier_id, po_plant: a.po_plant, purchase_order_no: docNo, table_po: tableForCheck });

// VALIDATE_QUANTITY reads item_id / item_name / item_desc / quantity of every row, children after their parent
const qtyRows = [];
const flatten = (rs) => {
  for (const row of Array.isArray(rs) ? rs : []) {
    const r = row || {};
    qtyRows.push({ item_id: r.item_id, item_name: r.item_name, item_desc: r.item_desc, quantity: r.quantity });
    flatten(r.children);
  }
};
if (!isDraft) flatten(rows);

// Filter unnecessary line + Count line (Issued)
const filtered = isDraft ? [] : list.filter((item) => (item.item_name || item.item_desc || item.item_id) && item.quantity > 0);
let savedLines = 0;
for (const line of filtered) savedLines += 1 + (Array.isArray(line.children) ? line.children.length : 0);

// Direct PI Zero Total Check (header fields only)
const piNeedConfirm = Number(a.auto_pi) === 1 && (parseFloat(a.po_total) || 0) <= 0 && a.create_pi !== "Yes";

// Map Approval PO Data: min / max unit price per line (parents 1, 2, ...; children 1/1, 1/2, ...), PO amount rule
const priced = [];
filtered.forEach((item, index) => {
  priced.push({ unit_price: item.unit_price, min_price: item.min_price, max_price: item.max_price, lineNo: `${index + 1}` });
  (Array.isArray(item.children) ? item.children : []).forEach((child, childIndex) => {
    priced.push({ unit_price: child.unit_price, min_price: child.min_price, max_price: child.max_price, lineNo: `${index + 1}/${childIndex + 1}` });
  });
});
const limitOf = (value) => {
  const n = parseFloat(value);
  return value == null || value === "" || Number.isNaN(n) || n === 0 ? null : n;
};
const minFailed = priced.filter((item) => {
  const minPrice = limitOf(item.min_price);
  return minPrice !== null && (parseFloat(item.unit_price) || 0) < minPrice;
});
const maxFailed = priced.filter((item) => {
  const maxPrice = limitOf(item.max_price);
  return maxPrice !== null && (parseFloat(item.unit_price) || 0) > maxPrice;
});
const minPriceResult = minFailed.length > 0 ? "failed" : "passed";
const maxPriceResult = maxFailed.length > 0 ? "failed" : "passed";
const amountResult = (parseFloat(a.po_total) || 0) > 0 ? "over" : "within";
const priceMessage = [
  ...minFailed.map((item) => `Line ${item.lineNo}: Unit Price ${item.unit_price} is below Min Price ${item.min_price}`),
  ...maxFailed.map((item) => `Line ${item.lineNo}: Unit Price ${item.unit_price} exceeds Max Price ${item.max_price}`),
].join("<br>");

// Distinct top-level item ids (digits only) for the internal-trading alias read
const itemIds = [...new Set(filtered.map((l) => String(l.item_id || "")).filter((id) => /^[0-9]{1,19}$/.test(id)))];
// The stored PO this save edits (Edit only: a Clone carries its source PO's id and line ids)
const rawId = a.page_status == "Edit" ? String(a.id || "").trim() : "";

return {
  docNo: docNo,
  draftRequiredFields: draftRequiredFields,
  draftRequiredEntry: draftRequiredEntry,
  requiredFields: requiredFields,
  requiredEntry: requiredEntry,
  lineItem: JSON.stringify(qtyRows),
  itemFields: "item_id,item_name,item_desc",
  quantityFields: "quantity",
  lineCount: filtered.length,
  savedLines: savedLines,
  piConfirm: piNeedConfirm ? 405 : 0,
  piGateOut: {
    pi_confirm: piNeedConfirm ? 405 : 0,
    msg: piNeedConfirm ? "This PO has 0 total amount. Do you wish to continue to create PI?" : "",
  },
  approvalData: {
    po_status: a.po_status,
    previous_status: a.previous_status,
    preq_id: a.preq_id,
    purchase_order_no: docNo,
    min_price_result: minPriceResult,
    max_price_result: maxPriceResult,
    amount_result: amountResult,
  },
  minPriceResult: minPriceResult,
  maxPriceResult: maxPriceResult,
  priceMessage: priceMessage,
  itemIdCsv: itemIds.length ? itemIds.join(",") : "0",
  poIdSql: /^[0-9]{1,19}$/.test(rawId) ? rawId : "0",
};

// Existing draft GR / PI of this PO (Get Draft GR / PI: numbers only)
const rows = [{{node:sql_draft_grpi.data}}][0];
const list = Array.isArray(rows) ? rows : rows ? [rows] : [];
let message = [];
let status = 'Passed';

const draftGRNo = list.filter((r) => r.kind === 'GR').map((r) => r.doc_no).filter(Boolean).join(', ');
if(draftGRNo) message.push(draftGRNo);

const draftPINo = list.filter((r) => r.kind === 'PI').map((r) => r.doc_no).filter(Boolean).join(', ');
if(draftPINo) message.push(draftPINo);

if(message.length > 0) {
  status = 'Failed'
}

return {
  status: status,
  message: status === 'Passed' ? '' : 'The purchase order has existing GR/PI records in draft status. Proceeding will delete these record: ' + message.join(', ')
}

const its = {{node:get_its_pre.data.data}};
const r = Array.isArray(its) ? its[0] : its;
const issued = ({{workflowparams:allData.po_status}}) === "Issued";
const isInternal = !!(issued && r && r.id && Number(r.auto_create_so) === 1);
const rawLinked = {{workflowparams:allData.linked_so_id}} || "";
const isLinked = issued && !!rawLinked;
// The linked Sales Order is created / updated by SO_SAVE in this same run with every line: above 500 lines the issue
// stops here, before anything is written (SO_SAVE at 2,000 lines is a separate plan).
const savedLines = Number({{node:code_pre.data.savedLines}}) || 0;
const sizeBlock = (isInternal || isLinked) && savedLines > 500;
return {
  sizeBlock: sizeBlock ? "YES" : "NO",
  sizeMsg: "This purchase order has " + savedLines + " lines. Issuing it to an internal trading supplier creates a linked Sales Order, " +
    "which supports at most 500 lines. Please split it into smaller purchase orders.",
  isInternal: isInternal,
  sellerOrg: r && r.seller_org_id ? r.seller_org_id : "",
  sellerCustomer: r && r.seller_customer_id ? r.seller_customer_id : "",
  isLinked: isLinked,
  linkedSoId: rawLinked || "0",
  runGate: (isInternal || isLinked)
};

const lines = {{workflowparams:allData.table_po}};
const aliasesRaw = {{node:search_alias_pre.data.data}};
const customerRaw = {{node:get_customer_pre.data.data}};
const currencyRaw = {{node:get_currency_pre.data.data}};
const linkedRaw = {{node:search_linked_so.data.data}};
const poCurrency = {{workflowparams:allData.po_currency}};
const autoSkip = {{workflowparams:allData.auto_so_skip}} === true;
const autoConfirmed = {{workflowparams:allData.auto_so_confirmed}} === true;
const unlinkConfirmed = {{workflowparams:allData.unlink_confirmed}} === true;
const swapConfirmed = {{workflowparams:allData.swap_confirmed}} === true;
const isLinked = {{node:code_its_pre.data.isLinked}} === true;
const isInternal = {{node:code_its_pre.data.isInternal}} === true;
const sellerOrg = {{node:code_its_pre.data.sellerOrg}};

const toArr = (x) => Array.isArray(x) ? x : (x ? [x] : []);
const one = (x) => Array.isArray(x) ? x[0] : x;
const aliasArr = toArr(aliasesRaw);
const aliasMap = {};
aliasArr.forEach((a) => { aliasMap[a.buyer_item_id + "|" + a.buyer_uom_id] = a; });
const stock = (lines || []).filter((l) => l.item_id && parseFloat(l.quantity) > 0);
const missing = [];
stock.forEach((l) => { if (!aliasMap[l.item_id + "|" + l.quantity_uom]) missing.push(l.item_name || l.item_id); });
const cur = one(currencyRaw);
const curCode = cur ? (cur.currency_code || "") : "";
const normCur = (c) => (c === "----" ? "MYR" : (c || ""));
const currencyMismatch = !!(poCurrency && curCode && normCur(poCurrency) !== normCur(curCode));
const customer = one(customerRaw);
const custName = customer && customer.customer_com_name ? customer.customer_com_name : "the seller organization";
const blocked = missing.length > 0 || currencyMismatch;
const eligible = !blocked;

const linkedSo = one(toArr(linkedRaw));
const soOrg = linkedSo ? String(linkedSo.organization_id || "") : "";
const sameSeller = eligible && !!soOrg && (soOrg === String(sellerOrg));
const soStatus = linkedSo ? (linkedSo.so_status || "") : "";
const soLines = (linkedSo && linkedSo.table_so) ? linkedSo.table_so : [];
const inProgress = (soStatus && soStatus !== "Issued") || soLines.some(function (l) {
  return parseFloat(l.delivered_qty || 0) > 0
    || parseFloat(l.planned_qty || 0) > 0
    || parseFloat(l.production_qty || 0) > 0
    || parseFloat(l.invoice_qty || 0) > 0
    || parseFloat(l.posted_qty || 0) > 0
    || l.line_status === "Processing" || l.line_status === "Completed";
});

let soConfirm = 0;
let msg = "";

if (isLinked) {
  if (!eligible) {
    if (!unlinkConfirmed) {
      soConfirm = 409;
      const reason = !isInternal ? "the supplier is no longer set up for internal trading"
        : (missing.length ? "these items are not linked in Item Alias: " + missing.join(", ")
          : "the purchase order currency no longer matches the seller organization");
      msg = "This purchase order no longer qualifies for internal trading (" + reason + "). The linked Sales Order will be unlinked.";
    }
  } else if (!sameSeller) {
    if (!swapConfirmed) {
      soConfirm = 410;
      msg = "The supplier changed to a different internal organization. The current linked Sales Order will be unlinked and a new one created for " + custName + ".";
    }
  } else {
    if (inProgress) {
      soConfirm = 411;
      msg = "The linked Sales Order is already being fulfilled (delivery / invoice / production has started) and cannot be changed.";
    }
  }
} else {
  if (blocked) {
    if (!autoSkip) {
      soConfirm = 406;
      msg = missing.length ? "The following items are not linked in Item Alias for the seller organization: " + missing.join(", ")
        : "PO currency (" + poCurrency + ") does not match the seller organization currency (" + curCode + ").";
    }
  } else {
    if (!autoConfirmed && !autoSkip) {
      soConfirm = 408;
      msg = "This purchase order qualifies for internal trading. A linked Sales Order will be created for " + custName + ".";
    }
  }
}

return { soConfirm: soConfirm, gateOut: { so_confirm: soConfirm, msg: msg } };

let updatedLineItem = [];
// The record Add Data / Update Data write, built from the payload once. Draft: every row + the draft marker. Issued:
// the rows Filter unnecessary line kept + the issued marker; when approval is needed, the header fields CHECK_APPROVAL
// handed back (it may have knocked the PO back to Draft, and it carries approval_condition) overlay it.
const a = {{workflowparams:allData}} || {};
const pre = {{node:code_pre.data.approvalData}} || {};
const needApproval = {{node:wf_check_approval.data.needApproval}};
const approved = {{node:wf_check_approval.data.data}};
let entry;
if (a.po_status == "Draft") {
  entry = { ...a, purchase_order_no: {{node:code_pre.data.docNo}} };
} else {
  entry = {
    ...a,
    purchase_order_no: {{node:code_pre.data.docNo}},
    table_po: (a.table_po || []).filter((item) => (item.item_name || item.item_desc || item.item_id) && item.quantity > 0),
    min_price_result: pre.min_price_result,
    max_price_result: pre.max_price_result,
    amount_result: pre.amount_result,
  };
  if (needApproval == "Yes" && approved && typeof approved === "object") Object.assign(entry, approved);
}

// The form sends back whatever approval_condition it loaded. Only the copy CHECK_APPROVAL
// just worked out is current; anything else (draft, no approval needed) is cleared.
if (needApproval != "Yes") {
  entry.approval_condition = {};
}

// table_po is written as one array, so the columns other flows own are taken from the stored line (read just now),
// never from the form: received_qty / created_received_qty (Goods Receiving), invoice_qty (Purchase Invoice),
// return_quantity / created_return_qty (Purchase Return). A line without a stored row (Add / Clone, a new line) keeps the
// form's values.
const stored = {};
let storedPoStatus = "";
const ownedRows = [{{node:sql_po_owned.data}}][0];
if (a.page_status == "Edit") {
  for (const r of Array.isArray(ownedRows) ? ownedRows : ownedRows ? [ownedRows] : []) {
    storedPoStatus = r.head_po_status || storedPoStatus;
    if (r.id !== undefined && r.id !== null && r.id !== "") stored[String(r.id)] = r;
  }
}
const dbNum = (v) => (v === undefined || v === null || v === "" ? null : Number(v));
const storedOf = (line) => (line && line.id !== undefined && line.id !== null && line.id !== "" ? stored[String(line.id)] : null);
const ownedFromDb = (line) => {
  const s = storedOf(line);
  if (!s) return line;
  return { ...line, received_qty: dbNum(s.received_qty), created_received_qty: dbNum(s.created_received_qty), invoice_qty: dbNum(s.invoice_qty),
    return_quantity: dbNum(s.return_quantity), created_return_qty: dbNum(s.created_return_qty) };
};
// line_status of a stored line: Goods Receiving moves it to Processing / Completed and a revert back to Issued, so the stored
// value decides (the form's copy may predate either); saved as Issued, a Draft / Issued line is Issued
const lineStatusOf = (line, fallback) => {
  const s = storedOf(line);
  if (!s) return fallback;
  if (s.line_status === "Processing" || s.line_status === "Completed") return s.line_status;
  if (entry.po_status === "Issued" && (!s.line_status || s.line_status === "Draft" || s.line_status === "Issued")) return "Issued";
  return fallback;
};

// alt_uom is re-stringified on every form load, so it grows with each save; it is kept as one JSON layer with the
// four keys Goods Receiving reads (alt_uom_id, alt_qty, base_qty, base_uom_id)
const altUom = (v) => {
  if (v === undefined || v === null || v === "") return v;
  try {
    let x = v;
    for (let i = 0; i < 64 && typeof x === "string"; i++) x = JSON.parse(x);
    const keep = (c) => (c && typeof c === "object" ? { alt_uom_id: c.alt_uom_id, alt_qty: c.alt_qty, base_qty: c.base_qty, base_uom_id: c.base_uom_id } : c);
    return JSON.stringify(Array.isArray(x) ? x.map(keep) : keep(x));
  } catch (e) {
    return v;
  }
};

// Header fields shared by every line, parent and child alike
const commonFields = {
  supplier_id: entry.po_supplier_id || "",
  plant_id: entry.po_plant || "",
  payment_term_id: entry.po_payment_terms || "",
  shipping_preference_id: entry.po_shipping_preference || "",
  billing_state_id: entry.billing_address_state || "",
  billing_country_id: entry.billing_address_country || "",
  shipping_state_id: entry.shipping_address_state || "",
  shipping_country_id: entry.shipping_address_country || "",
  organization_id: entry.organization_id,
  po_created_by: {{global:nickname}},
};

const round8 = (value) => Math.round((parseFloat(value) || 0) * 100000000) / 100000000;

const formatLine = (formLine) => {
  const poLineItem = ownedFromDb(formLine);
  const receivedQty = poLineItem.received_qty === null || poLineItem.received_qty === undefined || poLineItem.received_qty === '' ? 0 : parseFloat(poLineItem.received_qty);

  const out = {
    ...poLineItem,
    quantity: round8(poLineItem.quantity),
    unit_price: round8(poLineItem.unit_price),
    gross: round8(poLineItem.gross),
    discount: round8(poLineItem.discount),
    discount_amount: round8(poLineItem.discount_amount),
    tax_amount: round8(poLineItem.tax_amount),
    po_amount: round8(poLineItem.po_amount),
    min_price: round8(poLineItem.min_price),
    max_price: round8(poLineItem.max_price),
    received_qty: round8(receivedQty),
    outstanding_quantity: Math.max(0, round8((parseFloat(poLineItem.quantity) || 0) - receivedQty)),
    item_category_id: poLineItem.item_category_id || "",
    po_expected_date: poLineItem.po_expected_date ?? entry.po_expected_date,
  };
  if ("alt_uom" in poLineItem) out.alt_uom = altUom(poLineItem.alt_uom);
  return out;
};

for (const [index, poLineItem] of entry.table_po.entries()) {
  const lineStatus =
    !poLineItem.line_status ||
    poLineItem.line_status === "" ||
    poLineItem.line_status === "Draft"
      ? entry.po_status
      : poLineItem.line_status;

  const formattedItem = {
    ...formatLine(poLineItem),
    ...commonFields,
    line_index: index + 1,
    line_status: lineStatusOf(poLineItem, lineStatus),

    // If got child, give it the same formatting and header fields
    ...(Array.isArray(poLineItem.children) && {
      children: poLineItem.children.map((child, childIndex) => ({
        ...formatLine(child),
        ...commonFields,
        line_index: `${index + 1}/${childIndex + 1}`,
        line_status: lineStatusOf(child, lineStatus),
      })),
    }),
  };

  updatedLineItem.push(formattedItem);
}

entry.partially_received = !entry.partially_received || entry.partially_received === '' ? `0 / ${updatedLineItem.length}` : entry.partially_received;
entry.fully_received = !entry.fully_received || entry.fully_received === '' ? `0 / ${updatedLineItem.length}` : entry.fully_received;
entry.po_total_gross = round8(entry.po_total_gross);
entry.po_total_discount = round8(entry.po_total_discount);
entry.po_total_tax = round8(entry.po_total_tax);
entry.po_total = round8(entry.po_total);
entry.myr_total_amount = round8(entry.myr_total_amount);

entry.table_po = updatedLineItem;

// Goods Receiving moves an Issued PO to Processing / Completed: saving it as Issued (the form always asks for Issued) keeps
// that status. Lines above already took the requested status, so a new line still starts as Issued.
if (entry.po_status === "Issued" && (storedPoStatus === "Processing" || storedPoStatus === "Completed")) entry.po_status = storedPoStatus;

// Update Transaction Date: the items of the top-level lines (was Map Item IDs)
const itemIDs = [...new Set(updatedLineItem.filter((item) => item.item_id).map((item) => item.item_id))];

return { entry, itemIDs };

// Custom fields this edit would blank: the payload left the header object, or a line's, out
const missing = (v) => v === undefined || v === null;
const flat = (rows) => {
  const out = [];
  for (const r of Array.isArray(rows) ? rows : []) {
    if (!r || typeof r !== "object") continue;
    out.push(r);
    for (const c of Array.isArray(r.children) ? r.children : []) if (c && typeof c === "object") out.push(c);
  }
  return out;
};
const cf = [{{node:code_fillback.data.entry.custom_fields_b3w85tmv}}][0];
const lines = [{{node:code_fillback.data.entry.table_po}}][0];
const rawId = [{{node:code_fillback.data.entry.id}}][0];
const id = missing(rawId) ? "" : String(rawId).trim();
const lineKeys = ["custom_fields_va4w0xz3"];
const lineMiss = flat(lines).some((r) => lineKeys.some((k) => missing(r[k])));
return { need: /^[0-9]{1,20}$/.test(id) && (missing(cf) || lineMiss) ? "YES" : "NO", id: id };

// The stored custom fields for what this edit left out: the header as stored; each line by its id
const missing = (v) => v === undefined || v === null;
const flat = (rows) => {
  const out = [];
  for (const r of Array.isArray(rows) ? rows : []) {
    if (!r || typeof r !== "object") continue;
    out.push(r);
    for (const c of Array.isArray(r.children) ? r.children : []) if (c && typeof c === "object") out.push(c);
  }
  return out;
};
const cf = [{{node:code_fillback.data.entry.custom_fields_b3w85tmv}}][0];
const lines = [{{node:code_fillback.data.entry.table_po}}][0];
const got = [{{node:get_node_CfStored1.data.data}}][0];
const stored = (Array.isArray(got) ? got[0] : got) || {};
const natKey = null;
const storedRows = flat(stored["table_po"]);
const sentIds = new Set(flat(lines).map((r) => (missing(r.id) ? "" : String(r.id))).filter((x) => x));
const byId = new Map(storedRows.filter((r) => !missing(r.id) && r.id !== "").map((r) => [String(r.id), r]));
const byKey = new Map();
if (natKey) {
  for (const r of storedRows) {
    if (sentIds.has(String(r.id))) continue;
    const k = missing(r[natKey]) ? "" : String(r[natKey]);
    if (!k) continue;
    if (!byKey.has(k)) byKey.set(k, []);
    byKey.get(k).push(r);
  }
}
const fill = (row) => {
  if (!row || typeof row !== "object") return row;
  let src = !missing(row.id) && row.id !== "" ? byId.get(String(row.id)) : undefined;
  if (!src && natKey) {
    const queue = byKey.get(missing(row[natKey]) ? "" : String(row[natKey]));
    if (queue && queue.length) src = queue.shift();
  }
  const add = {};
  if (src) for (const k of Object.keys(src)) if (k.indexOf("custom_fields") === 0 && missing(row[k]) && !missing(src[k])) add[k] = src[k];
  let next = Object.keys(add).length ? Object.assign({}, row, add) : row;
  if (Array.isArray(row.children)) next = Object.assign({}, next, { children: row.children.map(fill) });
  return next;
};
return { ok: "YES", cf: missing(cf) ? (missing(stored["custom_fields_b3w85tmv"]) ? null : stored["custom_fields_b3w85tmv"]) : cf, lines: Array.isArray(lines) ? lines.map(fill) : lines };

// What the update writes: the payload's custom fields, or the stored ones where this edit left them out
const filled = [{{node:code_node_CfFill1.data}}][0];
if (filled && filled.ok === "YES") return { cf: filled.cf, lines: filled.lines };
const cf = [{{node:code_fillback.data.entry.custom_fields_b3w85tmv}}][0];
return { cf: cf === undefined ? null : cf, lines: [{{node:code_fillback.data.entry.table_po}}][0] };

// The saved PO's id: the row Add Data inserted (Add / Clone) or the PO this Edit updated. Its header is read back once,
// after approval, by Get PO Header; only the approval path reads the whole record (Get PO Snapshot).
const pageStatus = {{workflowparams:allData.page_status}};
const added = {{node:add_po.data.id}};
const addedId = Array.isArray(added) ? added[0] : added;
const id = String((pageStatus == "Add" || pageStatus == "Clone" ? addedId : {{workflowparams:allData.id}}) || "").trim();

return { poData: { id: id }, poIdSql: /^[0-9]{1,19}$/.test(id) ? id : "0" };

// The PO as saved above: Add Data's row (Add / Clone), else read back (Edit)
const addedRaw = {{node:add_po.data}};
const snapRaw = {{node:get_po_snap.data.data}};
let latestPOData = {{workflowparams:allData.page_status}} == 'Add' || {{workflowparams:allData.page_status}} == 'Clone'
  ? (Array.isArray(addedRaw) ? addedRaw[0] : addedRaw)
  : (Array.isArray(snapRaw) ? snapRaw[0] : snapRaw);

// Held back as a draft for approval -> number it now. 'issued' is the same marker
// Check Doc No uses; manual numbering (-9999) keeps the typed number.
if (
  latestPOData.purchase_order_no_type !== -9999 &&
  (latestPOData.previous_status === "Draft" || !latestPOData.previous_status) &&
  latestPOData.po_status !== "Issued"
) {
  latestPOData.purchase_order_no = "issued";
}
latestPOData.po_status = "Issued";

// Lines were saved with the header's Draft status. Issue them with the header so
// GR conversion picks them up.
const issueLine = (line) => ({
  ...line,
  line_status: !line.line_status || line.line_status === "Draft" ? "Issued" : line.line_status,
});

latestPOData.table_po = (latestPOData.table_po || []).map((line) => ({
  ...issueLine(line),
  ...(Array.isArray(line.children) && { children: line.children.map(issueLine) }),
}));

return { latestPOData };

// The saved PO as it stands now (after approval, if any): the header fields the rest of the workflow reads, typed as the
// get-node handed them on (ids and text as strings, auto_pi / po_total as numbers, preq_id as an array of id strings).
const rows = [{{node:sql_po_head.data}}][0];
const r = (Array.isArray(rows) ? rows[0] : rows) || {};
if (!r.id) throw new Error("PO_SAVE: the saved purchase order " + {{node:code_get_latest.data.poIdSql}} + " could not be read back");
const text = (v) => (v === undefined || v === null ? undefined : String(v));
const num = (v) => (v === undefined || v === null || v === "" ? undefined : Number(v));
// JSON_ARRAYAGG of the ids as text: arrives as JSON text (or already parsed)
let preq = r.preq_id_json;
if (typeof preq === "string") preq = preq ? JSON.parse(preq) : [];
const poData = {
  id: text(r.id),
  purchase_order_no: text(r.purchase_order_no),
  po_status: text(r.po_status),
  po_plant: text(r.po_plant),
  organization_id: text(r.organization_id),
  po_supplier_id: text(r.po_supplier_id),
  preq_id: (Array.isArray(preq) ? preq : []).map(String),
  po_total: num(r.po_total),
  auto_pi: num(r.auto_pi),
  create_pi: text(r.create_pi),
};

// SQL-safe forms of the keys Get On Order Lines / Items / Existing On Order interpolate: digits only, the PO number as hex
const digits = (v) => (/^[0-9]{1,19}$/.test(String(v || "")) ? String(v) : "0");
const hex = (s) => {
  let e = "";
  try {
    e = encodeURIComponent(String(s || ""));
  } catch (err) {
    return "";
  }
  let h = "";
  for (let i = 0; i < e.length; i++) {
    if (e[i] === "%") {
      h += e.substr(i + 1, 2);
      i += 2;
    } else {
      h += ("0" + e.charCodeAt(i).toString(16)).slice(-2);
    }
  }
  return h.toUpperCase();
};

return { poData: poData, poIdSql: digits(poData.id), orgSql: digits(poData.organization_id), poNoHex: hex(poData.purchase_order_no) };

// table_po is a tree: an item bundle is ONE row with its items under `children`.
// Only the items are materials -- the bundle row itself has no item_id -- so they
// are the rows on order, and reading the top level alone left them with no
// on_order_purchase_order row at all. Goods Receiving then had nothing to
// decrement on completion. Get On Order Lines returns the lines already flat,
// each bundle row followed by its items, in the order the PO read-back nests them.
const list = (x) => (Array.isArray(x) ? x : x ? [x] : []);
const text = (v) => (v === undefined || v === null || v === "" ? undefined : String(v));
const num = (v) => (v === undefined || v === null || v === "" ? undefined : Number(v));
const parse = (v) => {
  if (Array.isArray(v)) return v;
  try {
    const x = typeof v === "string" && v ? JSON.parse(v) : [];
    return Array.isArray(x) ? x : [];
  } catch (e) {
    return [];
  }
};

const head = {{node:code_resolve_latest.data.poData}} || {};
const poFull = { id: head.id, purchase_order_no: head.purchase_order_no, po_plant: head.po_plant, organization_id: head.organization_id };
// The rows as the get / search nodes handed them on: ids as strings, numbers as numbers, NULL columns absent
const latestLines = list({{node:sql_oo_lines.data}}).map((r) => ({
  id: text(r.id),
  item_id: text(r.item_id),
  quantity: num(r.quantity),
  quantity_uom: text(r.quantity_uom),
  preq_id: text(r.preq_id),
  preq_line_id: text(r.preq_line_id),
}));
const fetched = list({{node:sql_onorder.data}}).map((r) => ({
  id: text(r.id),
  po_id: text(r.po_id),
  po_line_id: text(r.po_line_id),
  material_id: text(r.material_id),
  purchase_order_number: r.purchase_order_number,
  purchase_order_line: num(r.purchase_order_line),
  received_qty: num(r.received_qty),
}));
const itemById = new Map();
for (const r of list({{node:sql_oo_items.data}})) {
  const id = String(r.id);
  if (!itemById.has(id)) itemById.set(id, { id: id, table_uom_conversion: parse(r.uom_json) });
}

const round8 = (n) => Math.round((parseFloat(n) || 0) * 100000000) / 100000000;

// The fetch is keyed on po_id OR purchase_order_number, because a PO number is not unique
// (purchase_order_no_type -9999 is user-typed) and rows written before po_id existed carry
// none. `mine` is this PO's own rows - the only ones we are ever allowed to delete.
// `orphan` are unstamped rows under the same number: adoptable, so an edit repairs one
// instead of adding a second row beside it, but never deleted (it may be a sibling's).
const poId = String(poFull.id);
const mine = fetched.filter(e => String(e.po_id || '') === poId);
const orphan = fetched.filter(e => !e.po_id && String(e.purchase_order_number) === String(poFull.purchase_order_no));
const existing = mine.concat(orphan);

const baseQtyFor = (line) => {
  const itemData = itemById.get(String(line.item_id));
  const altQty = parseFloat(line.quantity) || 0;
  let baseQty = altQty;
  if (itemData && Array.isArray(itemData.table_uom_conversion) && itemData.table_uom_conversion.length > 0) {
    const conv = itemData.table_uom_conversion.find(c => String(c.alt_uom_id) === String(line.quantity_uom));
    if (conv) baseQty = round8(altQty * parseFloat(conv.base_qty));
  }
  return baseQty;
};

const desired = [];
for (const [index, line] of latestLines.entries()) {
  const itemData = itemById.get(String(line.item_id));
  if (!itemData) continue;
  desired.push({
    po_line_id: line.id,
    purchase_order_number: poFull.purchase_order_no,
    material_id: line.item_id,
    purchase_order_line: index + 1,
    scheduled_qty: baseQtyFor(line),
    plant_id: poFull.po_plant,
    organization_id: poFull.organization_id,
    po_id: poFull.id,
    parent_id: line.preq_id || null,
    parent_line_id: line.preq_line_id || null
  });
}

const toAdd = [], toUpdate = [], toDelete = [];
const usedExistingIds = new Set();

// The first unused existing row, in fetch order, on po_line_id; else on material + line number (legacy rows).
// Indexed by key: the same row the linear scans picked, without an O(lines x rows) search.
const byLine = new Map();
const byMaterialLine = new Map();
for (const e of existing) {
  if (e.po_line_id != null) {
    const k = String(e.po_line_id);
    if (!byLine.has(k)) byLine.set(k, []);
    byLine.get(k).push(e);
  }
  const k2 = String(e.material_id) + "|" + Number(e.purchase_order_line);
  if (!byMaterialLine.has(k2)) byMaterialLine.set(k2, []);
  byMaterialLine.get(k2).push(e);
}
const firstUnused = (rows) => (rows || []).find((e) => !usedExistingIds.has(e.id));
const findExisting = (d) => {
  const m = firstUnused(byLine.get(String(d.po_line_id)));
  if (m) return m;
  return firstUnused(byMaterialLine.get(String(d.material_id) + "|" + Number(d.purchase_order_line)));
};

// No Add/Clone shortcut. `existing` is already scoped to this PO, so on a genuine Add it is
// empty and every line falls through to toAdd anyway; reconciling uniformly means a re-entry
// over an already-issued PO updates its own rows instead of laying down a duplicate set.
for (const d of desired) {
  const match = findExisting(d);
  if (!match) {
    toAdd.push({
      purchase_order_number: d.purchase_order_number,
      material_id: d.material_id,
      purchase_order_line: d.purchase_order_line,
      scheduled_qty: d.scheduled_qty,
      open_qty: d.scheduled_qty,
      received_qty: 0,
      plant_id: d.plant_id,
      organization_id: d.organization_id,
      po_id: d.po_id,
      po_line_id: d.po_line_id,
      parent_id: d.parent_id,
      parent_line_id: d.parent_line_id
    });
  } else {
    usedExistingIds.add(match.id);
    const received = Math.max(0, round8(match.received_qty || 0));
    const newOpen = Math.max(0, round8(d.scheduled_qty - received));
    // Re-stamp every PO-owned column, not just the quantities: po_plant and the line's item
    // stay editable while the PO is Issued, and an adopted legacy row has no po_id/po_line_id
    // at all. received_qty is owned by the GR flow - never write it from here.
    toUpdate.push({
      id: match.id,
      scheduled_qty: d.scheduled_qty,
      open_qty: newOpen,
      purchase_order_number: d.purchase_order_number,
      purchase_order_line: d.purchase_order_line,
      material_id: d.material_id,
      plant_id: d.plant_id,
      organization_id: d.organization_id,
      po_id: d.po_id,
      po_line_id: d.po_line_id,
      parent_id: d.parent_id,
      parent_line_id: d.parent_line_id
    });
  }
}

// Only rows this PO owns are swept, so an unmatched orphan stays put rather than being
// deleted out from under whichever PO it really belongs to.
for (const e of mine) {
  if (!usedExistingIds.has(e.id)) toDelete.push({ id: e.id });
}

const preqIds = head.preq_id || [];
const hasPreq = Array.isArray(preqIds) && preqIds.length > 0;

// Written in slices of <= 250 rows per add / update / delete call
const SLICE = 250;
const slices = (rows) => {
  const out = [];
  for (let i = 0; i < rows.length; i += SLICE) out.push({ rows: rows.slice(i, i + SLICE) });
  return out;
};

return {
  addSlices: slices(toAdd),
  updateSlices: slices(toUpdate),
  deleteSlices: slices(toDelete),
  hasAdds: toAdd.length > 0,
  hasUpdates: toUpdate.length > 0,
  hasDeletes: toDelete.length > 0,
  hasPreq: hasPreq,
};

// On-order add slice: the loop's current <= 250 rows (Add On Order)
const slice = [{{node:loop_oo_add}}][0] || {};
const rows = Array.isArray(slice.rows) ? slice.rows : [];
return { rows: rows, count: rows.length };

// On-order update slice: the loop's current <= 250 rows (Update On Order)
const slice = [{{node:loop_oo_update}}][0] || {};
const rows = Array.isArray(slice.rows) ? slice.rows : [];
return { rows: rows, count: rows.length };

// On-order delete slice: the loop's current <= 250 rows (Delete On Order)
const slice = [{{node:loop_oo_delete}}][0] || {};
const rows = Array.isArray(slice.rows) ? slice.rows : [];
return { rows: rows, count: rows.length };

const poID = {{node:code_resolve_latest.data.poData.id}};
// The PO's top-level lines (Get On Order Lines; bundle items are nested under their row in the read-back)
const poLineItem = ([{{node:sql_oo_lines.data}}][0] || []).filter((r) => !r.parent_id).map((r) => ({
  id: r.id == null ? undefined : String(r.id),
  preq_line_id: r.preq_line_id == null ? undefined : String(r.preq_line_id),
  quantity: r.quantity == null ? undefined : Number(r.quantity),
}));
const preqData = {{node:search_preq.data.data}};
const toArr = (x) => Array.isArray(x) ? x : (x ? [x] : []);
const round8 = (value) => Math.round((parseFloat(value) || 0) * 100000000) / 100000000;
let latestPREQData = [];

if(preqData && preqData.length > 0) {
  for(const preq of preqData) {
    let processedItems = preq.table_pr.map(item => {
      const matchingPoLines = poLineItem.filter(po => String(po.preq_line_id) === String(item.id));
      const newItem = { ...item };

      if(matchingPoLines.length > 0) {
        // PO line qty shares the PREQ line UOM (PRconvertPO sets quantity = pr_line_qty),
        // so order_qty accumulates in line units (NOT the base scheduled_qty stored on on_order).
        // This PO's contribution = sum of its lines that point at this PREQ line.
        const thisPoQty = matchingPoLines.reduce((sum, po) => sum + (parseFloat(po.quantity) || 0), 0);
        const prevPoIds = toArr(item.po_id).map(String);
        const alreadyLinked = prevPoIds.includes(String(poID));
        // EDIT (this PO already linked): replace its prior contribution. ADD (new link): append to the running total.
        // Assumes the supported 1 PREQ -> 1 PO flow; on edit this keeps the latest PO quantity authoritative.
        const baseQty = alreadyLinked ? 0 : parseFloat(item.order_qty || 0);
        newItem.order_qty = round8(baseQty + thisPoQty);
        newItem.po_id = [...new Set([...prevPoIds, String(poID)])];
        newItem.po_line_id = [...new Set([...toArr(item.po_line_id).map(String), ...matchingPoLines.map(po => String(po.id))])];
      }

      return newItem;
    });

    let preqStatus = preq.preq_status;
    if(preq.preq_type === 'Contract' && preq.preq_status !== 'Force Completed') {
      const isCompleted = processedItems.every(item =>
        parseFloat(item.pr_line_qty) === parseFloat(item.order_qty || 0)
      );
      preqStatus = isCompleted ? 'Completed' : 'Processing';
    } else if(preq.preq_status !== 'Force Completed') {
      preqStatus = 'Completed';
    }

    processedItems = processedItems.map((it) => {
      return { ...it, line_status: preqStatus };
    });

    latestPREQData.push({
      id: preq.id,
      preq_status: preqStatus,
      table_pr: processedItems,
    });
  }
}

return { latestPREQData };

const its = {{node:get_its.data.data}};
const r = Array.isArray(its) ? its[0] : its;
const isInternal = !!(r && r.id && Number(r.auto_create_so) === 1);
const rawLinked = {{workflowparams:allData.linked_so_id}} || "";
const isLinked = !!rawLinked;
return {
  isInternal: isInternal,
  isLinked: isLinked,
  runGate: (isInternal || isLinked),
  linkedSoId: rawLinked || "0",
  sellerOrg: r && r.seller_org_id ? r.seller_org_id : "",
  sellerCustomer: r && r.seller_customer_id ? r.seller_customer_id : "",
  pricingSource: r && r.pricing_source ? r.pricing_source : "po_price",
  paymentTermSource: r && r.payment_term_source ? r.payment_term_source : "seller_customer"
};

const rows = {{node:search_addr.data.data}};
const arr = Array.isArray(rows) ? rows : (rows ? [rows] : []);
const countryIds = [...new Set(arr.map(a => a.address_country_id).filter(Boolean))];
const stateIds = [...new Set(arr.map(a => a.adddress_state).filter(Boolean))];
return {
  countryIds: countryIds.length ? countryIds : ["0"],
  stateIds: stateIds.length ? stateIds : ["0"]
};

const aliasesRaw = {{node:search_alias.data.data}};
const arr = Array.isArray(aliasesRaw) ? aliasesRaw : (aliasesRaw ? [aliasesRaw] : []);
const ids = [...new Set(arr.map((a) => a.seller_item_id).filter(Boolean))];
return { sellerItemIds: ids.length ? ids : ["0"] };

const po = {{node:get_po_full.data.data}};
const aliasesRaw = {{node:search_alias.data.data}};
const customerRaw = {{node:get_customer.data.data}};
const accRaw = {{node:get_acc.data.data}};
const currencyRaw = {{node:get_currency.data.data}};
const ruleRaw = {{node:get_so_rule.data.data}};
const sellerItemsRaw = {{node:search_seller_items.data.data}};
const existingRaw = {{node:search_existing_link.data.data}};
const addrRaw = {{node:search_addr.data.data}};
const shipPurposeRaw = {{node:get_ship_purpose.data.data}};
const countriesRaw = {{node:search_country.data.data}};
const statesRaw = {{node:search_state.data.data}};
const sellerOrg = {{node:code_its.data.sellerOrg}};
const sellerCustomer = {{node:code_its.data.sellerCustomer}};
const pricingSource = {{node:code_its.data.pricingSource}};
const paymentTermSource = {{node:code_its.data.paymentTermSource}};
const autoSkip = {{workflowparams:allData.auto_so_skip}} === true;
const autoConfirmed = {{workflowparams:allData.auto_so_confirmed}} === true;
const unlinkConfirmed = {{workflowparams:allData.unlink_confirmed}} === true;
const swapConfirmed = {{workflowparams:allData.swap_confirmed}} === true;
const linkedRaw = {{node:search_linked_so2.data.data}};
const isLinked = po.linked_so_id ? true : false;

const toArr = (x) => Array.isArray(x) ? x : (x ? [x] : []);
const one = (x) => Array.isArray(x) ? x[0] : x;

const aliasArr = toArr(aliasesRaw);
const customer = one(customerRaw);
const acc = one(accRaw);
const currency = one(currencyRaw);
const rule = one(ruleRaw);
const sellerItems = toArr(sellerItemsRaw);
const existingArr = toArr(existingRaw);
const itemMap = {};
sellerItems.forEach((it) => { itemMap[it.id] = it; });
const addrArr = toArr(addrRaw);
const shipPurpose = one(shipPurposeRaw);
const countries = toArr(countriesRaw);
const states = toArr(statesRaw);

const alreadyLinked = existingArr.length > 0;

// alias map keyed by buyer item + buyer uom
const aliasMap = {};
aliasArr.forEach((a) => { aliasMap[a.buyer_item_id + "|" + a.buyer_uom_id] = a; });

// --- setup-driven resolvers (current value implemented; default == current) ---
// Pricing source: how the SO unit price is derived from the PO line.
const round8 = (value) => Math.round((parseFloat(value) || 0) * 100000000) / 100000000;

const computePrice = (l, rate) => {
  switch (pricingSource) {
    case "po_price":
    default:
      // Preserve the line total across the UOM conversion.
      return round8((parseFloat(l.unit_price) || 0) / rate);
  }
};
// NOTE: tax is intentionally NOT carried from the PO — PO and SO tax setups are
// independent (different tax_code/rate), so the SO is created tax-free.
// Payment-term source: where the SO header payment term comes from.
const computePaymentTerm = () => {
  switch (paymentTermSource) {
    case "seller_customer":
    default:
      return customer ? (customer.customer_payment_term_id || null) : null;
  }
};

// Packing / weight helpers (mirror SOchangeItem.buildPackingWeightData), driven
// off the seller Item record + the seller UOM. unrestricted_qty is intentionally
// NOT set (not required for an auto-created SO).
// An item may define several packing rows per uom_id. There is no buyer-side
// packing choice to carry across orgs (item_alias maps only the order UOM), so
// take the first row but log when the choice was ambiguous.
const getPackingDetail = (tpd, uom) => {
  if (!Array.isArray(tpd) || !uom) return null;
  const rows = tpd.filter((c) => c.uom_id === uom);
  if (rows.length > 1) console.log('PO->SO: ambiguous packing for UOM', uom, '- using first of', rows.length);
  return rows[0] || null;
};
const getBaseQty = (tuc, uom) => {
  if (!Array.isArray(tuc) || !uom) return 1;
  const c = tuc.find((x) => x.alt_uom_id === uom);
  return c && c.base_qty ? c.base_qty : 1;
};

const lines = (po.table_po || []).filter((l) => l.item_id && parseFloat(l.quantity) > 0);
const missing = [];
const soLines = [];
lines.forEach((l, i) => {
  const a = aliasMap[l.item_id + "|" + l.quantity_uom];
  if (!a) { missing.push(l.item_name || l.item_id); return; }
  const rate = parseFloat(a.conversion_rate) || 1;
  const soQty = round8((parseFloat(l.quantity) || 0) * rate);
  const sit = itemMap[a.seller_item_id] || null;
  const pd = sit ? getPackingDetail(sit.table_packing_detail, a.seller_uom_id) : null;
  const packingConversion = pd && pd.quantity ? pd.quantity : 1;
  const packingUOM = pd ? (pd.packing_uom_id || "") : "";
  const baseQty = sit ? getBaseQty(sit.table_uom_conversion, a.seller_uom_id) : 1;
  const weightConversion = round8((Number(sit ? sit.net_weight : 0) || 0) * baseQty);
  const packingQty = packingConversion ? round8(soQty / packingConversion) : 0;
  const netWeight = round8(soQty * weightConversion);
  soLines.push({
    item_name: a.seller_item_id,
    item_id: sit ? (sit.material_name || "") : "",
    so_desc: sit && sit.material_desc ? sit.material_desc : (l.item_desc || ""),
    item_category_id: sit ? (sit.item_category || "") : "",
    custom_fields: sit ? (sit.custom_fields || null) : null,
    so_quantity: soQty,
    so_item_uom: a.seller_uom_id,
    so_item_price: computePrice(l, rate),
    so_gross: round8(l.gross),
    so_discount: round8(l.discount),
    so_discount_amount: round8(l.discount_amount),
    so_tax_preference: "",
    so_tax_percentage: 0,
    so_tax_amount: 0,
    so_tax_inclusive: 0,
    so_amount: round8((parseFloat(l.gross) || 0) - (parseFloat(l.discount_amount) || 0)),
    packing_uom: packingUOM,
    packing_conversion: round8(packingConversion),
    packing_qty: packingQty,
    weight_conversion: weightConversion,
    net_weight: netWeight,
    line_index: i + 1,
    source_po_line_item_id: l.id
  });
});

// currency gate
const curCode = currency ? (currency.currency_code || "") : "";
const exRate = (curCode && curCode !== "----" && curCode !== "MYR")
  ? (currency.currency_buying_rate || 1) : 1;
const normCur = (c) => (c === "----" ? "MYR" : (c || ""));
const currencyMismatch = !!(po.po_currency && curCode && normCur(po.po_currency) !== normCur(curCode));

// addresses
const cMap = {}; countries.forEach((c) => { cMap[c.id] = c.country_name; });
const sMap = {}; states.forEach((s) => { sMap[s.id] = s.state_name; });
const shipPurposeId = shipPurpose ? shipPurpose.id : null;
const fmt = (a, stateName, countryName, typeUpper) => {
  const ln = [a.address_line_1, a.address_line_2, a.address_line_3, a.address_line_4].filter((x) => x);
  const addressLines = ln.join((ln[ln.length - 1] || "").endsWith(",") ? " " : ", ");
  const cp = [a.address_city, a.address_postal_code, a.adddress_state ? stateName : "", a.address_country_id ? countryName : ""].filter((x) => x);
  const cityDetails = cp.join((cp[cp.length - 1] || "").endsWith(",") ? " " : ", ");
  const att = a.address_attention ? "\nAttention: " + a.address_attention : "";
  const person = [a.address_name, a.address_phone].filter((x) => x).join(" | ");
