const poData = {{node:code_resolve_latest.data.poData}} || {};
const previousStatus = {{workflowparams:allData.previous_status}} || "";

// A Direct Invoice PO (auto_pi = 1) gets its PI once, on the save that first issues
// it. A later edit of the issued PO must not invoice it again, so an order that was
// already Issued / Processing / Completed before this save is left alone. A PO held
// for approval is not Issued yet; it gets its PI on the run that approves it.
const isFirstIssue = !["Issued", "Processing", "Completed"].includes(previousStatus);
const hasAmount =
  (parseFloat(poData.po_total) || 0) > 0 || poData.create_pi === "Yes";

const run =
  Number(poData.auto_pi) === 1 &&
  poData.po_status === "Issued" &&
  isFirstIssue &&
  hasAmount;

console.log("Direct PI gate", poData.purchase_order_no, { run, previousStatus });

