// Direct Invoice: one Completed PI for the PO just issued. The mapping is the one
// PO_CONVERT_PI uses (5. Map PI Data), cut down to a single PO.
const po = {{node:get_direct_pi_po.data.data}} || {};
const convertTo = "completed";
const docFormat = {{node:get_direct_pi_format.data.data}} || {};

// A relation column can come back as an object rather than an id. An id-typed
// column on the invoice that receives null fails a BigInt conversion, so an
// empty one is blanked rather than written as null.
const referenceId = (value) => {
  if (value && typeof value === "object") return value.id || null;
  return value || null;
};

const toNumber = (value) => parseFloat(value) || 0;

// Custom fields travel as one object; a JSON column can arrive as text, and a NULL one is left off the row.
const customFields = (value) => {
  if (typeof value === "string") {
    try {
      value = JSON.parse(value);
    } catch (e) {
      return {};
    }
  }
  return value && typeof value === "object" && !Array.isArray(value) ? value : {};
};

const round8 = (value) => Math.round(toNumber(value) * 100000000) / 100000000;

// The invoice date on the engine's own clock. toISOString() would shift it to
// UTC, which before 08:00 local is a day early.
const localDateString = (date) => {
  const pad = (n) => String(n).padStart(2, "0");

  return [date.getFullYear(), pad(date.getMonth() + 1), pad(date.getDate())].join("-");
};

// ==========================================================================
// ITEM BUNDLES
// --------------------------------------------------------------------------
// A bundle is one PO line with the bundle's items beneath it, and it is
// invoiced as a whole. table_po arrives either with the items nested under the
// bundle line's `children`, or as flat rows pointing back through parent_id,
// so both are read and turned into one list with each bundle's items directly
// after their bundle. table_pi is built as a tree again: the bundle is one row
// carrying its items under `children`, as the PI form hands it to PI_SAVE.
// ==========================================================================
const flattenPoLines = (lines) => {
  const rows = lines || [];

  const childrenOf = (line) => {
    const nested = Array.isArray(line.children) ? line.children : [];
    if (nested.length > 0) return nested;

    return rows.filter(
      (row) =>
        row.parent_id !== undefined &&
        row.parent_id !== null &&
        row.parent_id !== "" &&
        String(row.parent_id) === String(line.id),
    );
  };

  const claimed = new Set();

  rows.forEach((line) => {
    childrenOf(line).forEach((child) => {
      if (child && child.id !== undefined && child.id !== null) {
        claimed.add(String(child.id));
      }
    });
  });

  const flat = [];

  rows.forEach((line) => {
    if (claimed.has(String(line.id))) return;

    flat.push({ line: line, parentId: null });

    childrenOf(line).forEach((child) => {
      flat.push({ line: child, parentId: String(line.id) });
    });
  });

  return flat;
};

// What is left to invoice on a PO line, the same figure the PI form offers
// when a PO is picked there. PI_SAVE checks it again before it saves.
const remainingQty = (line) =>
  Math.max(0, toNumber(line.quantity) - toNumber(line.invoice_qty));

const exchangeRateOf = (po) => toNumber(po.exchange_rate) || 1;

const mapLineItem = (line, po, lineIndex, plantID) => {
  const invoiceQty = remainingQty(line);
  const orderQty = toNumber(line.quantity);
  const unitPrice = toNumber(line.unit_price);

  // The PO line's amounts are for its whole quantity; the invoice carries the
  // share of them that is still to be invoiced.
  const ratio = orderQty > 0 ? invoiceQty / orderQty : 0;
  let discount = toNumber(line.discount);

  if (line.discount_uom === "Amount") {
    discount = discount * ratio;
  }

  return {
    material_id: referenceId(line.item_id) || "",
    material_name: line.item_name,
    item_bundle_id: referenceId(line.item_bundle_id) || "",
    item_desc: line.item_desc || "",
    more_desc: line.more_desc || "",
    purchase_order_no: po.purchase_order_no,
    order_qty: round8(orderQty),
    received_qty: round8(line.received_qty),
    invoice_qty: round8(invoiceQty),
    available_inv_qty: round8(invoiceQty),
    quantity_uom: referenceId(line.quantity_uom) || "",
    order_unit_price: round8(unitPrice),
    order_gross: round8(unitPrice * invoiceQty),
    order_discount: round8(discount),
    discount_uom: line.discount_uom,
    discount_amount: round8(toNumber(line.discount_amount) * ratio),
    tax_preference: referenceId(line.tax_preference) || "",
    tax_percent: line.tax_percent,
    tax_amount: round8(toNumber(line.tax_amount) * ratio),
    tax_inclusive: line.tax_inclusive,
    invoice_amount: round8(toNumber(line.po_amount) * ratio),
    line_remark_1: line.line_remark_1 || "",
    line_remark_2: line.line_remark_2 || "",
    goods_receiving_no: "",
    gr_line_id: "",
    line_gr_id: "",
    line_po_id: po.id,
    po_line_id: line.id,
    item_category_id: referenceId(line.item_category_id) || "",
    line_index: lineIndex,
    plant_id: plantID,
    tariff_id: line.tariff_id,
    payment_term_id: referenceId(po.po_payment_terms) || "",
    further_description: line.further_description || "",
    project_id: line.project_id ?? null,
    custom_fields_y78jfz24: customFields(line.custom_fields_va4w0xz3),
  };
};

// The invoice lines for one order, numbered on from `lineNumber`. A line with
// nothing left to invoice is left out, and a bundle line left out takes its
// items with it.
const buildPiLines = (po, lineNumber, plantID) => {
  const lines = [];
  const rowByPoLine = {};

  for (const entry of flattenPoLines(po.table_po)) {
    const parentRow = entry.parentId ? rowByPoLine[entry.parentId] : null;

    if (entry.parentId && !parentRow) continue;
    if (remainingQty(entry.line) <= 0) continue;

    if (parentRow) {
      if (!Array.isArray(parentRow.children)) parentRow.children = [];

      parentRow.children.push(
        mapLineItem(
          entry.line,
          po,
          `${parentRow.line_index}-${parentRow.children.length + 1}`,
          plantID,
        ),
      );
      continue;
    }

    lineNumber++;

    const row = mapLineItem(entry.line, po, lineNumber, plantID);
    lines.push(row);
    rowByPoLine[String(entry.line.id)] = row;
  }

  // A bundle is worth what its items come to, which is how the PO totals it,
  // so the bundle line's amounts are replaced by the sum of its items.
  for (const row of lines) {
    if (!Array.isArray(row.children) || row.children.length === 0) continue;

    const sumOf = (key) =>
      row.children.reduce((total, child) => total + toNumber(child[key]), 0);
    const bundleQty = toNumber(row.invoice_qty);

    row.order_gross = round8(sumOf("order_gross"));
    row.discount_amount = round8(sumOf("discount_amount"));
    row.tax_amount = round8(sumOf("tax_amount"));
    row.invoice_amount = round8(sumOf("invoice_amount"));
    row.order_unit_price = bundleQty > 0 ? round8(row.order_gross / bundleQty) : 0;
  }

  return { lines, lineNumber };
};

// Totals are counted on the top-level lines only: a bundle is counted once,
// through its bundle line.
const calculateTotals = (lines, exchangeRate) => {
  const sumOf = (key) => lines.reduce((total, line) => total + toNumber(line[key]), 0);
  const invoiceTotal = sumOf("invoice_amount");

  return {
    invoice_subtotal: round8(sumOf("order_gross")),
    invoice_total_discount: round8(sumOf("discount_amount")),
    invoice_taxes_amount: round8(sumOf("tax_amount")),
    invoice_total: round8(invoiceTotal),
    myr_total_amount: round8(invoiceTotal * exchangeRate),
  };
};

const mapHeaderData = (record, pos, lines, plantID) => {
