    pi_status: convertTo === "draft" ? "Draft" : "Completed",
    posted_status: convertTo === "draft" ? "" : "Unposted",
    purchase_invoice_no: convertTo === "draft" ? "draft" : "issued",
    purchase_invoice_no_type: docFormat.id,
    invoice_date: localDateString(new Date()),
    supplier_name: referenceId(record.po_supplier_id),
    plant_id: plantID,
    organization_id: record.organization_id,
